SELECT cr.cr_order_number, cr.cr_return_quantity, cr.cr_net_loss, ib_ret.ib_lower_bound AS returning_income_lower, ib_ret.ib_upper_bound AS returning_income_upper, ib_ref.ib_lower_bound AS refunded_income_lower, ib_ref.ib_upper_bound AS refunded_income_upper, CASE WHEN ib_ret.ib_income_band_sk = ib_ref.ib_income_band_sk THEN 'Same' WHEN ib_ret.ib_lower_bound > ib_ref.ib_lower_bound THEN 'Higher' ELSE 'Lower' END AS returning_vs_refunded_income, SUM(cr.cr_net_loss) OVER (ORDER BY cr.cr_order_number ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss, ROW_NUMBER() OVER (ORDER BY cr.cr_net_loss DESC) AS net_loss_rank FROM catalog_returns cr JOIN household_demographics hd_ret ON cr.cr_returning_hdemo_sk = hd_ret.hd_demo_sk JOIN income_band ib_ret ON hd_ret.hd_income_band_sk = ib_ret.ib_income_band_sk JOIN household_demographics hd_ref ON cr.cr_refunded_hdemo_sk = hd_ref.hd_demo_sk JOIN income_band ib_ref ON hd_ref.hd_income_band_sk = ib_ref.ib_income_band_sk WHERE cr.cr_net_loss IS NOT NULL ORDER BY net_loss_rank LIMIT 100
